 25	/**
 26	 * The y coord of every split line of the first yAxis, sorted ascending.
 27	 */
 28	function getSplitLineYCoords(chart: EChartsType): number[] {
 29	    const coords: number[] = [];
 30	    getGraphicElements(chart, 'yAxis', 0).forEach(function (el) {
 31	        // The split lines are the only `Line` elements that go across the grid,
 32	        // the axis ticks are much shorter.
 33	        if (el.type === 'line' && (el as any).anid && /^line_/.test((el as any).anid)) {
 34	            coords.push((el as any).shape.y1);
 35	        }
 36	    });
 37	    return coords.sort(function (a, b) {
 38	        return a - b;
 39	    });
 40	}
