+import { EChartsType } from '@/src/echarts';
+import { EChartsOption } from '@/src/export/option';
+import { createChart, getECModel, getGraphicElements, removeChart } from '../../../core/utHelper';
+import CartesianAxisModel from '@/src/coord/cartesian/AxisModel';
+
+/**
+ * The y coord of every split line of the first yAxis, sorted ascending.
+ */
+function getSplitLineYCoords(chart: EChartsType): number[] {
+    const coords: number[] = [];
+    getGraphicElements(chart, 'yAxis', 0).forEach(function (el) {
+        // The split lines are the only `Line` elements that go across the grid,
+        // the axis ticks are much shorter.
+        if (el.type === 'line' && (el as any).anid && /^line_/.test((el as any).anid)) {
+            coords.push((el as any).shape.y1);
+        }
+    });
+    return coords.sort(function (a, b) {
+        return a - b;
+    });
+}
+
+function makeOption(splitLine: object): EChartsOption {
+    return {
+        animation: false,
+        grid: { left: 40, right: 20, top: 20, bottom: 30 },
+        xAxis: { type: 'category', data: ['a', 'b', 'c', 'd'] },
+        yAxis: {
+            type: 'value',
+            min: 0,
+            max: 400,
+            interval: 100,
+            splitLine: splitLine
+        },
+        series: [{ type: 'line', data: [100, 200, 300, 400] }]
+    } as EChartsOption;
+}
+
+describe('component/axis/splitLineMinMax', function () {
+
+    let chart: EChartsType;
+    beforeEach(function () {
+        chart = createChart({ width: 400, height: 300 });
+    });
+    afterEach(function () {
+        removeChart(chart);
+    });
+
+    it('should draw all of the split lines by default', function () {
+        chart.setOption(makeOption({ show: true }));
+
+        const coords = getSplitLineYCoords(chart);
+        // 0, 100, 200, 300, 400
+        expect(coords.length).toEqual(5);
+
+        const axis = (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
